package com.spaceagent.platform.tooling;
import com.fasterxml.jackson.databind.ObjectMapper;import com.spaceagent.platform.identity.api.*;import com.spaceagent.platform.identity.application.IdentityApplicationService;import com.spaceagent.platform.identity.domain.TenantRole;import com.spaceagent.platform.identity.infrastructure.persistence.PostgresIdentityRepository;import com.spaceagent.platform.tooling.api.McpMarketplaceApplicationApi.*;import com.spaceagent.platform.tooling.application.McpMarketplaceApplicationService;import com.spaceagent.platform.tooling.domain.*;import com.spaceagent.platform.tooling.infrastructure.persistence.*;import com.spaceagent.shared.id.UuidGenerator;import org.flywaydb.core.Flyway;import org.junit.jupiter.api.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.DriverManagerDataSource;import org.testcontainers.containers.PostgreSQLContainer;import org.testcontainers.junit.jupiter.*;import java.time.Instant;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
@Testcontainers(disabledWithoutDocker=true) class PlatformGithubMcpOAuthPostgresTest{@Container static final PostgreSQLContainer<?> PG=new PostgreSQLContainer<>("pgvector/pgvector:pg17").withDatabaseName("github_mcp_oauth").withUsername("spaceagent").withPassword("spaceagent");@BeforeAll static void migrate(){Flyway.configure().dataSource(ds()).locations("classpath:db/platform-server","classpath:db/platform-runtime").load().migrate();}
 @Test void oauthStateIsEncryptedBoundExpiringAndSingleUse(){var j=new JdbcTemplate(ds());var ids=new UuidGenerator();var ir=new PostgresIdentityRepository(j);var ia=new IdentityApplicationService(ir,ids,Instant::now);String t=ia.createTenant(new CreateTenantCommand("OAuth","oauth-pg")).id(),u=ia.createUser(new CreateUserCommand(t,"oauth@example.com","OAuth")).id();ia.addTenantMembership(new AddTenantMembershipCommand(t,u,TenantRole.OWNER));var marketRepo=new PostgresMcpMarketplaceRepository(j);var market=new McpMarketplaceApplicationService(marketRepo,ia,new Cipher(),new ObjectMapper(),ids,Instant::now);var install=market.install(new InstallCommand(t,u,marketRepo.findEntryBySlug("github").orElseThrow().id(),McpInstallationScope.USER,null));var connection=market.connect(new ConnectCommand(t,u,install.id(),"https://mcp.github.example/mcp",McpAuthType.OAUTH2,Map.of()));var states=new PostgresMcpOAuthStateRepository(j);Instant n=Instant.now();states.save(new McpOAuthState(ids.nextId(),connection.id(),connection.revision(),t,u,"a".repeat(64),new Cipher().encrypt("provider-session"),n.plusSeconds(60),n,null));String stored=j.queryForObject("SELECT encrypted_provider_session FROM platform_mcp_oauth_states WHERE state_hash=?",String.class,"a".repeat(64));assertFalse(stored.contains("provider-session"));assertTrue(states.consume("a".repeat(64),t,u,n.plusSeconds(1)).isPresent());assertTrue(states.consume("a".repeat(64),t,u,n.plusSeconds(2)).isEmpty());assertEquals(110L,j.queryForObject("SELECT count(*) FROM flyway_schema_history WHERE success",Long.class));}
 private static DriverManagerDataSource ds(){return new DriverManagerDataSource(PG.getJdbcUrl(),PG.getUsername(),PG.getPassword());}private static class Cipher implements McpConnectionSecretCipher{public String encrypt(String v){return "cipher:"+Base64.getEncoder().encodeToString(v.getBytes());}public String decrypt(String v){return new String(Base64.getDecoder().decode(v.substring(7)));}}
}
